export const envelope = [35, 46, 75];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 4;

  // Palette extraction from world theme
  const stonePri = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAcc = api.theme?.stone?.accent || "minecraft:chiseled_stone_bricks";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const groundPlinth = api.theme?.ground?.plinth || "minecraft:smooth_stone";
  const groundPave = api.theme?.ground?.pavement || "minecraft:cobblestone";
  const woodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const woodFence = api.theme?.wood?.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:spruce_trapdoor";

  // Silver rigid airship & steel duralumin blocks
  const hullSkin = "minecraft:light_gray_concrete";
  const hullRib = "minecraft:polished_andesite";
  const hullStripe = "minecraft:red_concrete";
  const ironLattice = "minecraft:iron_bars";
  const ironBlock = "minecraft:iron_block";
  const glassBlock = "minecraft:tinted_glass";
  const lightBeacon = "minecraft:sea_lantern";
  const chainY = "minecraft:chain[axis=y]";
  const chainZ = "minecraft:chain[axis=z]";

  // Safe placement helper
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Foundation helper respecting terrain height
  function fillFoundation(x, z, topLocalY, block) {
    const gh = api.heightAt(x, z);
    const bottomY = Math.max(0, SEAT_Y + gh);
    const topY = Math.max(bottomY, topLocalY);
    for (let y = topY; y >= bottomY; y--) {
      set(x, y, z, block);
    }
    // Solid sub-base down to envelope floor if ground drops
    for (let y = bottomY - 1; y >= 0; y--) {
      set(x, y, z, groundPlinth);
    }
  }

  // ==========================================
  // 1. MOORING MAST & WINCH BASE
  // ==========================================
  const mastX = 17;
  const mastZ = 12;

  // Ground apron & approach pathway
  for (let x = 11; x <= 23; x++) {
    for (let z = 6; z <= 18; z++) {
      fillFoundation(x, z, SEAT_Y, groundPave);
    }
  }
  for (let x = 16; x <= 18; x++) {
    for (let z = 0; z <= 5; z++) {
      fillFoundation(x, z, SEAT_Y, groundPave);
    }
  }

  // 4 Main Concrete Footings
  const pierCoords = [
    [12, 7], [22, 7],
    [12, 17], [22, 17]
  ];
  for (const [px, pz] of pierCoords) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        fillFoundation(px + dx, pz + dz, SEAT_Y + 2, groundPlinth);
      }
    }
    set(px, SEAT_Y + 3, pz, stoneAcc);
  }

  // Winch & Control House at Mast Base (Y: SEAT_Y to SEAT_Y + 5)
  for (let x = 15; x <= 19; x++) {
    for (let z = 10; z <= 14; z++) {
      fillFoundation(x, z, SEAT_Y, groundPlinth);
      for (let y = SEAT_Y + 1; y <= SEAT_Y + 5; y++) {
        const isWall = (x === 15 || x === 19 || z === 10 || z === 14);
        if (isWall) {
          if (z === 10 && x === 17 && (y === SEAT_Y + 1 || y === SEAT_Y + 2)) {
            // Doorway left open for interior compiler fitout
            continue;
          }
          if ((x === 15 || x === 19) && z === 12 && y === SEAT_Y + 2) {
            set(x, y, z, glassBlock);
          } else {
            set(x, y, z, stonePri);
          }
        } else if (y === SEAT_Y + 5) {
          set(x, y, z, stonePri);
        }
      }
    }
  }

  // Tapered Steel Lattice Mast Legs (Y: 6 to 28)
  for (let y = 6; y <= 28; y++) {
    const u = (y - 6) / 22.0;
    const off = 5.0 - u * 3.2; // 5.0 at base -> 1.8 at top

    const corners = [
      [Math.round(mastX - off), Math.round(mastZ - off)],
      [Math.round(mastX + off), Math.round(mastZ - off)],
      [Math.round(mastX - off), Math.round(mastZ + off)],
      [Math.round(mastX + off), Math.round(mastZ + off)],
    ];

    for (const [cx, cz] of corners) {
      set(cx, y, cz, y % 3 === 0 ? ironBlock : hullRib);
    }

    // Horizontal tie frames every 4 blocks
    if (y % 4 === 0) {
      const minX = Math.round(mastX - off);
      const maxX = Math.round(mastX + off);
      const minZ = Math.round(mastZ - off);
      const maxZ = Math.round(mastZ + off);
      for (let x = minX; x <= maxX; x++) {
        set(x, y, minZ, ironLattice);
        set(x, y, maxZ, ironLattice);
      }
      for (let z = minZ; z <= maxZ; z++) {
        set(minX, y, z, ironLattice);
        set(maxX, y, z, ironLattice);
      }
    }

    // Central elevator / ladder tube
    set(mastX, y, mastZ, ironLattice);
    set(mastX, y, mastZ - 1, "minecraft:ladder[facing=south]");
  }

  // Lower & Middle Service Platforms
  for (const platY of [14, 22]) {
    const r = platY === 14 ? 3 : 2;
    for (let dx = -r; dx <= r; dx++) {
      for (let dz = -r; dz <= r; dz++) {
        const px = mastX + dx;
        const pz = mastZ + dz;
        set(px, platY, pz, hullRib);
        if (Math.abs(dx) === r || Math.abs(dz) === r) {
          set(px, platY + 1, pz, ironLattice);
        }
      }
    }
  }

  // Mast Head & Mooring Deck (Y: 29 to 34)
  for (let dx = -3; dx <= 3; dx++) {
    for (let dz = -3; dz <= 3; dz++) {
      if (Math.abs(dx) + Math.abs(dz) <= 5) {
        set(mastX + dx, 29, mastZ + dz, ironBlock);
        if (Math.abs(dx) + Math.abs(dz) === 5 || Math.abs(dx) === 3 || Math.abs(dz) === 3) {
          set(mastX + dx, 30, mastZ + dz, ironLattice);
        }
      }
    }
  }

  // Mooring Control Cupola (Y: 30 to 33)
  for (let x = 15; x <= 19; x++) {
    for (let z = 10; z <= 14; z++) {
      for (let y = 30; y <= 33; y++) {
        const isPerim = (x === 15 || x === 19 || z === 10 || z === 14);
        if (isPerim) {
          set(x, y, z, y === 31 || y === 32 ? glassBlock : ironBlock);
        } else if (y === 33) {
          set(x, y, z, hullRib);
        }
      }
    }
  }

  // Mast Top Beacon & Aerial
  for (let y = 34; y <= 36; y++) {
    set(mastX, y, mastZ, stoneWall);
  }
  set(mastX, 37, mastZ, lightBeacon);

  // Mooring Arm / Gangway Spindle (Connecting Mast to Airship Nose at Z = 16)
  for (let z = 13; z <= 16; z++) {
    for (let x = 16; x <= 18; x++) {
      set(x, 31, z, ironBlock); // gangway floor
      set(x, 32, z, x === 17 ? "minecraft:air" : ironLattice); // sides
      set(x, 33, z, ironBlock); // roof
    }
    set(mastX, 32, z, ironBlock); // heavy central spindle core
  }

  // Mooring Guyline Anchors on Ground
  const guyAnchors = [
    [17, 2], [6, 12], [28, 12]
  ];
  for (const [gx, gz] of guyAnchors) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        fillFoundation(gx + dx, gz + dz, SEAT_Y + 1, stonePri);
      }
    }
    set(gx, SEAT_Y + 2, gz, stoneAcc);
    // Guyline chains angling up to mast
    for (let step = 1; step <= 8; step++) {
      const cy = Math.round(SEAT_Y + 2 + (22 - (SEAT_Y + 2)) * (step / 8.0));
      const cx = Math.round(gx + (mastX - gx) * (step / 8.0));
      const cz = Math.round(gz + (mastZ - gz) * (step / 8.0));
      set(cx, cy, cz, chainY);
    }
  }

  // ==========================================
  // 2. RIGID AIRSHIP HULL
  // ==========================================
  const shipY0 = 32;
  const shipZStart = 16;
  const shipZEnd = 68;
  const shipLen = shipZEnd - shipZStart;

  // Streamlined teardrop radius profile function
  function getHullRadius(z) {
    if (z <= shipZStart || z >= shipZEnd) return 1.0;
    const t = (z - shipZStart) / shipLen;
    // Asymmetric aerodynamic profile: max diameter around 42% of length
    const r = 8.3 * (2.02 * Math.pow(t, 0.42) * Math.pow(1.0 - t, 0.52));
    return Math.max(1.0, r);
  }

  for (let z = shipZStart; z <= shipZEnd; z++) {
    const R = getHullRadius(z);
    const isRib = (z % 5 === 0);
    const isBulkhead = (z % 10 === 0 && z > 20 && z < 64);
    const minX = Math.floor(mastX - R - 1);
    const maxX = Math.ceil(mastX + R + 1);
    const minY = Math.floor(shipY0 - R - 1);
    const maxY = Math.ceil(shipY0 + R + 1);

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        const dx = x - mastX;
        const dy = y - shipY0;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist <= R) {
          const isOuterSkin = (dist >= R - 1.15);

          if (isOuterSkin) {
            // Hull skin detailing
            if (Math.abs(dy) <= 0.6) {
              // Equatorial livery stripe
              set(x, y, z, hullStripe);
            } else if (isRib || Math.abs(dx) <= 0.6 || Math.abs(dy) <= 0.6 || Math.abs(Math.abs(dx) - Math.abs(dy)) <= 0.5) {
              // Longitudinal stringers & transverse frame ribs
              set(x, y, z, hullRib);
            } else {
              set(x, y, z, hullSkin);
            }
          } else if (isBulkhead) {
            // Internal wire bracing / bulkheads with central passage
            if (dist > 1.8) {
              set(x, y, z, ironLattice);
            }
          }

          // Interior Keel Catwalk along belly
          const keelY = Math.floor(shipY0 - R + 1.2);
          if (y === keelY && Math.abs(dx) <= 1 && z >= 18 && z <= 64) {
            set(x, y, z, woodPlanks);
          }
          if (y === keelY + 1 && Math.abs(dx) === 1 && z >= 18 && z <= 64) {
            set(x, y, z, woodFence);
          }
        }
      }
    }
  }

  // Mooring Nose Cone Cap (Z = 16)
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      set(mastX + dx, shipY0 + dy, shipZStart, ironBlock);
    }
  }

  // Tail Cone Tip (Z = 68 to 70)
  set(mastX, shipY0, 69, hullRib);
  set(mastX, shipY0, 70, lightBeacon); // White stern navigation light

  // ==========================================
  // 3. CRUCIFORM EMPENNAGE (TAIL FINS)
  // ==========================================
  for (let z = 52; z <= 68; z++) {
    const u = (z - 52) / 16.0;
    const finHeight = u * 5.8;
    const R = getHullRadius(z);
    const isRudder = (z >= 63);

    // Top Vertical Fin
    const topFinMinY = Math.floor(shipY0 + R - 0.8);
    const topFinMaxY = Math.floor(shipY0 + R + finHeight);
    for (let y = topFinMinY; y <= topFinMaxY; y++) {
      set(mastX, y, z, isRudder ? hullStripe : hullSkin);
      // Leading/trailing edge reinforcement
      if (y === topFinMaxY || z === 52 || z === 68) {
        set(mastX, y, z, hullRib);
      }
    }

    // Bottom Vertical Fin
    const btmFinMinY = Math.floor(shipY0 - R - finHeight);
    const btmFinMaxY = Math.ceil(shipY0 - R + 0.8);
    for (let y = btmFinMinY; y <= btmFinMaxY; y++) {
      set(mastX, y, z, isRudder ? hullStripe : hullSkin);
      if (y === btmFinMinY || z === 52 || z === 68) {
        set(mastX, y, z, hullRib);
      }
    }

    // Port Horizontal Fin (West / -X)
    const portFinMinX = Math.floor(mastX - R - finHeight);
    const portFinMaxX = Math.ceil(mastX - R + 0.8);
    for (let x = portFinMinX; x <= portFinMaxX; x++) {
      set(x, shipY0, z, isRudder ? hullStripe : hullSkin);
      if (x === portFinMinX || z === 52 || z === 68) {
        set(x, shipY0, z, hullRib);
      }
    }

    // Starboard Horizontal Fin (East / +X)
    const stbdFinMinX = Math.floor(mastX + R - 0.8);
    const stbdFinMaxX = Math.ceil(mastX + R + finHeight);
    for (let x = stbdFinMinX; x <= stbdFinMaxX; x++) {
      set(x, shipY0, z, isRudder ? hullStripe : hullSkin);
      if (x === stbdFinMaxX || z === 52 || z === 68) {
        set(x, shipY0, z, hullRib);
      }
    }
  }

  // Navigation lights on fin tips
  set(mastX, 42, 68, lightBeacon); // Top fin white beacon
  set(6, shipY0, 68, "minecraft:red_concrete"); // Port red light
  set(28, shipY0, 68, "minecraft:emerald_block"); // Starboard green light

  // ==========================================
  // 4. CONTROL GONDOLA (UNDERSLUNG BRIDGE)
  // ==========================================
  // Forward bottom at Z = 24 to 33, Y = 20 to 24
  for (let z = 24; z <= 33; z++) {
    for (let x = 15; x <= 19; x++) {
      // Floor at Y = 20
      set(x, 20, z, hullRib);

      for (let y = 21; y <= 24; y++) {
        const isNose = (z === 24);
        const isTail = (z === 33);
        const isWall = (x === 15 || x === 19 || isNose || isTail);

        if (y === 24) {
          // Roof attaches firmly into hull belly
          set(x, y, z, ironBlock);
        } else if (isWall) {
          if (isNose || (y === 22 && (x === 15 || x === 19) && z <= 30)) {
            // Panoramic bridge windows
            set(x, y, z, glassBlock);
          } else {
            set(x, y, z, hullRib);
          }
        }
      }
    }
  }

  // Access ladder connecting Gondola to Keel Walkway
  for (let y = 21; y <= 26; y++) {
    set(mastX, y, 32, "minecraft:ladder[facing=south]");
  }

  // ==========================================
  // 5. ENGINE POWER CARS (NACELLES)
  // ==========================================
  const nacelles = [
    { x: 10, y: 25, z: 41, side: "port" },
    { x: 24, y: 25, z: 41, side: "stbd" },
    { x: 11, y: 24, z: 52, side: "port" },
    { x: 23, y: 24, z: 52, side: "stbd" }
  ];

  for (const nac of nacelles) {
    // 3x3x5 streamlined streamlined car body
    for (let z = nac.z - 2; z <= nac.z + 2; z++) {
      for (let dx = -1; dx <= 1; dx++) {
        for (let dy = -1; dy <= 1; dy++) {
          const nx = nac.x + dx;
          const ny = nac.y + dy;
          if (z === nac.z - 2) {
            // Radiator / intake front
            set(nx, ny, z, ironLattice);
          } else if (z === nac.z + 2) {
            // Tail cone
            set(nx, ny, z, dx === 0 && dy === 0 ? ironBlock : hullRib);
          } else {
            set(nx, ny, z, (dx === 0 && dy === 0) ? ironBlock : hullRib);
          }
        }
      }
    }

    // Pusher Propeller at aft of nacelle (z = nac.z + 3)
    const propZ = nac.z + 3;
    set(nac.x, nac.y, propZ, ironBlock);
    set(nac.x, nac.y + 1, propZ, woodTrapdoor);
    set(nac.x, nac.y - 1, propZ, woodTrapdoor);
    set(nac.x + 1, nac.y, propZ, woodTrapdoor);
    set(nac.x - 1, nac.y, propZ, woodTrapdoor);

    // Structural Struts anchoring nacelle to airship hull
    const dir = nac.side === "port" ? 1 : -1;
    for (let step = 1; step <= 3; step++) {
      set(nac.x + dir * step, nac.y + step, nac.z, ironLattice);
      set(nac.x + dir * step, nac.y + step, nac.z - 1, ironLattice);
    }
  }

  // ==========================================
  // 6. RESULT DECLARATION
  // ==========================================
  return {
    name: "Moored Rigid Airship and Mooring Mast",
    seatY: SEAT_Y,
    anchors: {
      front: [17, SEAT_Y, 0],
      door: [17, SEAT_Y, 10],
      mast_top: [17, 30, 12],
      gondola: [17, 21, 24]
    },
    interiors: [
      {
        min: [16, SEAT_Y + 1, 11],
        max: [18, SEAT_Y + 4, 13],
        kind: "quarters"
      },
      {
        min: [16, 21, 25],
        max: [18, 23, 31],
        kind: "bridge"
      },
      {
        min: [16, 25, 34],
        max: [18, 27, 44],
        kind: "hall"
      }
    ]
  };
}

vintage_biplane.source:
export const envelope = [15, 12, 15];

export default function build(api) {
  const blocks = new Map();

  function set(x, y, z, block) {
    if (x >= 0 && x < 15 && y >= 0 && y < 12 && z >= 0 && z < 15) {
      blocks.set(`${x},${y},${z}`, { x, y, z, block });
    }
  }

  // Theme fallbacks for world-aligned carpentry and stone
  const themeWood = api.theme?.wood?.planks || "minecraft:oak_planks";
  const themeFence = api.theme?.wood?.fence || "minecraft:oak_fence";
  const themeStairs = api.theme?.wood?.stairs || "minecraft:oak_stairs";
  const themeSlab = api.theme?.wood?.slab || "minecraft:oak_slab";
  const themePlinth = api.theme?.ground?.plinth || "minecraft:stone_bricks";

  // 5 Distinct Interwar Aviation Liveries (Plugin Variation)
  const variantIndex = (api.instance.index + Math.floor(api.random() * 5)) % 5;

  const liveries = [
    // Variant 0: RAF Tiger Moth Flight Trainer (Trainer Yellow & Polished Aluminum)
    {
      name: "raf_trainer",
      body: "minecraft:yellow_terracotta",
      trim: "minecraft:yellow_concrete",
      wingCore: "minecraft:yellow_terracotta",
      wingLeading: "minecraft:birch_stairs",
      wingTrailing: "minecraft:birch_slab",
      wingTip: "minecraft:birch_stairs",
      cowl: "minecraft:iron_block",
      cowlAccent: "minecraft:polished_andesite",
      strut: "minecraft:birch_fence",
      propWood: "minecraft:dark_oak_planks",
      propSlab: "minecraft:dark_oak_slab",
      insigniaA: "minecraft:blue_concrete",
      insigniaB: "minecraft:red_concrete",
      engineType: "inline",
      propStyle: "vertical",
      accessory: "ladder"
    },
    // Variant 1: Civilian Aerobatics & Air-Racer (Crimson Red & Cream Birch)
    {
      name: "barnstormer",
      body: "minecraft:red_terracotta",
      trim: "minecraft:red_concrete",
      wingCore: "minecraft:red_terracotta",
      wingLeading: "minecraft:oak_stairs",
      wingTrailing: "minecraft:birch_slab",
      wingTip: "minecraft:oak_stairs",
      cowl: "minecraft:polished_andesite",
      cowlAccent: "minecraft:smooth_stone",
      strut: "minecraft:oak_fence",
      propWood: "minecraft:spruce_planks",
      propSlab: "minecraft:spruce_slab",
      insigniaA: "minecraft:birch_planks",
      insigniaB: "minecraft:yellow_concrete",
      engineType: "radial",
      propStyle: "four_blade",
      accessory: "fuel_cart"
    },
    // Variant 2: Royal Navy Fleet Scout (Deep Sea Blue & Silver Sandstone)
    {
      name: "navy_scout",
      body: "minecraft:blue_terracotta",
      trim: "minecraft:light_gray_concrete",
      wingCore: "minecraft:smooth_sandstone",
      wingLeading: "minecraft:smooth_sandstone_stairs",
      wingTrailing: "minecraft:smooth_sandstone_slab",
      wingTip: "minecraft:smooth_sandstone_stairs",
      cowl: "minecraft:iron_block",
      cowlAccent: "minecraft:smooth_stone",
      strut: "minecraft:spruce_fence",
      propWood: "minecraft:iron_block",
      propSlab: "minecraft:smooth_stone_slab",
      insigniaA: "minecraft:white_concrete",
      insigniaB: "minecraft:blue_concrete",
      engineType: "radial",
      propStyle: "horizontal",
      accessory: "tie_downs"
    },
    // Variant 3: British Racing Green Courier & Air Mail Plane
    {
      name: "postal_courier",
      body: "minecraft:green_terracotta",
      trim: "minecraft:yellow_terracotta",
      wingCore: "minecraft:spruce_planks",
      wingLeading: "minecraft:spruce_stairs",
      wingTrailing: "minecraft:spruce_slab",
      wingTip: "minecraft:spruce_stairs",
      cowl: "minecraft:polished_deepslate",
      cowlAccent: "minecraft:iron_block",
      strut: "minecraft:dark_oak_fence",
      propWood: "minecraft:dark_oak_planks",
      propSlab: "minecraft:dark_oak_slab",
      insigniaA: "minecraft:yellow_concrete",
      insigniaB: "minecraft:black_concrete",
      engineType: "inline_twin",
      propStyle: "diagonal",
      accessory: "cargo_dolly"
    },
    // Variant 4: Doped Linen Pioneer Reconnaissance Biplane
    {
      name: "canvas_pioneer",
      body: "minecraft:smooth_sandstone",
      trim: "minecraft:stripped_birch_wood",
      wingCore: "minecraft:birch_planks",
      wingLeading: "minecraft:birch_stairs",
      wingTrailing: "minecraft:birch_slab",
      wingTip: "minecraft:birch_stairs",
      cowl: "minecraft:smooth_stone",
      cowlAccent: "minecraft:polished_andesite",
      strut: "minecraft:spruce_fence",
      propWood: "minecraft:oak_planks",
      propSlab: "minecraft:oak_slab",
      insigniaA: "minecraft:red_concrete",
      insigniaB: "minecraft:blue_concrete",
      engineType: "radial_spoked",
      propStyle: "vertical",
      accessory: "starter_trolley"
    }
  ];

  const livery = liveries[variantIndex];
  const seatY = 2; // Node-local Y meeting flat ground

  // -------------------------------------------------------------
  // 1. FUSELAGE STRUCTURE (Z = 1 to 13, centered at X = 7)
  // -------------------------------------------------------------

  // Cowl & Engine Nose (Z = 1..2)
  for (let x = 6; x <= 8; x++) {
    for (let y = 4; y <= 6; y++) {
      for (let z = 1; z <= 2; z++) {
        const isCore = (x === 7 && y === 5);
        set(x, y, z, isCore ? livery.cowlAccent : livery.cowl);
      }
    }
  }

  // Engine detailing (Radial rocker covers or inline exhaust stubs)
  if (livery.engineType === "radial" || livery.engineType === "radial_spoked") {
    set(7, 5, 1, "minecraft:polished_basalt[axis=z]");
    set(6, 5, 1, "minecraft:iron_bars");
    set(8, 5, 1, "minecraft:iron_bars");
    set(7, 6, 1, "minecraft:iron_bars");
    set(7, 4, 1, "minecraft:iron_bars");
  } else {
    // Inline engine side exhaust stacks
    set(5, 5, 2, "minecraft:hopper");
    set(9, 5, 2, "minecraft:hopper");
    set(5, 5, 3, "minecraft:hopper");
    set(9, 5, 3, "minecraft:hopper");
  }

  // Front deck & Firewall (Z = 3)
  for (let x = 6; x <= 8; x++) {
    set(x, 4, 3, livery.body);
    set(x, 5, 3, livery.body);
    set(x, 6, 3, livery.trim);
  }
  set(7, 6, 3, "minecraft:smooth_stone_slab[type=bottom]");

  // Cockpit & Center Fuselage (Z = 4 to 7)
  for (let z = 4; z <= 7; z++) {
    // Floor & belly (solid wing spar bridge)
    for (let x = 6; x <= 8; x++) {
      set(x, 4, z, livery.body);
    }
    // Fuselage walls
    set(6, 5, z, livery.body);
    set(8, 5, z, livery.body);

    // Deck & Coaming
    set(6, 6, z, livery.trim);
    set(8, 6, z, livery.trim);
  }

  // Cockpit Interior
  set(7, 5, 4, "minecraft:polished_blackstone"); // Instrument panel
  set(7, 6, 4, "minecraft:glass_pane"); // Windscreen
  set(7, 5, 5, "minecraft:dark_oak_stairs[facing=south,half=bottom]"); // Front seat
  set(7, 5, 6, "minecraft:dark_oak_stairs[facing=south,half=bottom]"); // Pilot seat
  set(7, 6, 7, "minecraft:dark_oak_stairs[facing=south,half=bottom]"); // Padded headrest
  set(7, 5, 7, livery.body);

  // Rear Fuselage (Tail Boom: Z = 8 to 11)
  for (let z = 8; z <= 10; z++) {
    for (let x = 6; x <= 8; x++) {
      set(x, 4, z, livery.body);
      set(x, 5, z, livery.body);
    }
    set(7, 6, z, livery.trim); // Turtledeck ridge
  }

  // Tapering to Tail Cone (Z = 11 to 13)
  for (let z = 11; z <= 13; z++) {
    set(7, 4, z, livery.body);
    set(7, 5, z, livery.body);
  }

  // -------------------------------------------------------------
  // 2. LOWER WING (Y = 4, Z = 4 to 6, Span X = 1 to 13)
  // -------------------------------------------------------------
  for (let x = 1; x <= 13; x++) {
    // Wing core
    set(x, 4, 5, livery.wingCore);

    // Leading edge
    set(x, 4, 4, `${livery.wingLeading}[facing=north,half=bottom]`);

    // Trailing edge
    set(x, 4, 6, `${livery.wingTrailing}[type=bottom]`);
  }
  // Wingtips rounded edges
  set(1, 4, 5, `${livery.wingTip}[facing=west,half=bottom]`);
  set(13, 4, 5, `${livery.wingTip}[facing=east,half=bottom]`);
  set(1, 4, 4, `${livery.wingTip}[facing=north,half=bottom]`);
  set(13, 4, 4, `${livery.wingTip}[facing=north,half=bottom]`);

  // Pilot step plate on left wing root
  set(5, 4, 6, "minecraft:polished_andesite_slab[type=bottom]");

  // -------------------------------------------------------------
  // 3. UPPER WING (Y = 7, Z = 3 to 5, Span X = 0 to 14, Staggered Forward)
  // -------------------------------------------------------------
  for (let x = 0; x <= 14; x++) {
    // Main wing chord
    set(x, 7, 4, livery.wingCore);

    // Aerodynamic leading edge
    set(x, 7, 3, `${livery.wingLeading}[facing=north,half=bottom]`);

    // Trailing edge
    set(x, 7, 5, `${livery.wingTrailing}[type=bottom]`);
  }

  // Rounded upper wingtips
  set(0, 7, 4, `${livery.wingTip}[facing=west,half=bottom]`);
  set(14, 7, 4, `${livery.wingTip}[facing=east,half=bottom]`);
  set(0, 7, 3, `${livery.wingTip}[facing=north,half=bottom]`);
  set(14, 7, 3, `${livery.wingTip}[facing=north,half=bottom]`);

  // Navigation lights on upper wingtips
  set(0, 7, 3, "minecraft:red_stained_glass"); // Port (Red)
  set(14, 7, 3, "minecraft:emerald_block"); // Starboard (Green)

  // Upper Wing Insignia / Cockades
  set(2, 7, 4, livery.insigniaA);
  set(3, 7, 4, livery.insigniaB);
  set(11, 7, 4, livery.insigniaB);
  set(12, 7, 4, livery.insigniaA);

  // Center Upper Wing Fuel Gravity Tank & Cutout
  set(7, 7, 4, livery.cowlAccent);
  set(7, 8, 4, "minecraft:polished_andesite_slab[type=bottom]"); // Fuel filler cap
  // Cockpit visibility cutout at (7, 7, 5) remains open air

  // -------------------------------------------------------------
  // 4. STRUTS & RIGGING
  // -------------------------------------------------------------
  // Center Cabane Struts (Connecting fuselage shoulders to upper wing)
  set(6, 6, 4, livery.strut);
  set(8, 6, 4, livery.strut);

  // Interplane Struts (Left wing: X = 3, Right wing: X = 11)
  for (let y = 5; y <= 6; y++) {
    // Left forward & aft struts
    set(3, y, 4, livery.strut);
    set(3, y, 5, livery.strut);
    // Right forward & aft struts
    set(11, y, 4, livery.strut);
    set(11, y, 5, livery.strut);
  }

  // Diagonal Flying Wires / Bracing
  set(4, 5, 4, "minecraft:iron_bars");
  set(10, 5, 4, "minecraft:iron_bars");
  set(2, 6, 4, "minecraft:iron_bars");
  set(12, 6, 4, "minecraft:iron_bars");

  // -------------------------------------------------------------
  // 5. TAIL ASSEMBLY (Empennage)
  // -------------------------------------------------------------
  // Horizontal Stabilizer & Elevators (Y = 5, Z = 11 to 13, X = 4 to 10)
  for (let x = 4; x <= 10; x++) {
    set(x, 5, 11, `${livery.wingLeading}[facing=north,half=bottom]`);
    set(x, 5, 12, livery.wingCore);
    set(x, 5, 13, `${livery.wingTrailing}[type=bottom]`);
  }

  // Vertical Fin & Rudder (X = 7, Z = 10 to 13, Y = 6 to 10)
  set(7, 6, 10, `${livery.wingLeading}[facing=north,half=bottom]`); // Dorsal fin fillet
  set(7, 6, 11, livery.trim);
  set(7, 7, 11, `${livery.wingLeading}[facing=north,half=bottom]`);

  for (let y = 6; y <= 9; y++) {
    set(7, y, 12, livery.trim); // Rudder post
    set(7, y, 13, livery.insigniaA); // Rudder fabric
  }
  set(7, 9, 12, `${livery.wingLeading}[facing=north,half=bottom]`);
  set(7, 10, 13, livery.insigniaB); // Rudder tip

  // Antenna Mast & Aerial Wire
  set(7, 9, 4, "minecraft:iron_bars"); // Upper wing mast
  set(7, 9, 5, "minecraft:chain[axis=z]");
  set(7, 9, 7, "minecraft:chain[axis=z]");
  set(7, 9, 9, "minecraft:chain[axis=z]");
  set(7, 10, 11, "minecraft:chain[axis=z]");
  set(7, 10, 12, "minecraft:iron_bars"); // Connects to tail fin

  // -------------------------------------------------------------
  // 6. PROPELLER & NOSE SPINNER (Z = 0, Centered at [7, 5, 0])
  // -------------------------------------------------------------
  set(7, 5, 0, livery.cowlAccent); // Spinner hub dome

  if (livery.propStyle === "vertical" || livery.propStyle === "radial_spoked") {
    set(7, 4, 0, livery.propWood);
    set(7, 3, 0, `${livery.propSlab}[type=bottom]`);
    set(7, 6, 0, livery.propWood);
    set(7, 7, 0, `${livery.propSlab}[type=bottom]`);
  } else if (livery.propStyle === "horizontal") {
    set(6, 5, 0, livery.propWood);
    set(5, 5, 0, `${livery.propSlab}[type=bottom]`);
    set(8, 5, 0, livery.propWood);
    set(9, 5, 0, `${livery.propSlab}[type=bottom]`);
  } else if (livery.propStyle === "four_blade") {
    set(7, 4, 0, livery.propWood);
    set(7, 3, 0, `${livery.propSlab}[type=bottom]`);
    set(7, 6, 0, livery.propWood);
    set(7, 7, 0, `${livery.propSlab}[type=bottom]`);
    set(6, 5, 0, livery.propWood);
    set(5, 5, 0, `${livery.propSlab}[type=bottom]`);
    set(8, 5, 0, livery.propWood);
    set(9, 5, 0, `${livery.propSlab}[type=bottom]`);
  } else {
    // Diagonal 45-degree prop
    set(6, 4, 0, livery.propWood);
    set(5, 3, 0, `${livery.propSlab}[type=bottom]`);
    set(8, 6, 0, livery.propWood);
    set(9, 7, 0, `${livery.propSlab}[type=bottom]`);
  }

  // -------------------------------------------------------------
  // 7. LANDING GEAR & CHOCKS (Seat plane Y = 2)
  // -------------------------------------------------------------
  // Main Axle Beam (Y = 3, Z = 4, X = 6 to 8)
  for (let x = 6; x <= 8; x++) {
    set(x, 3, 4, "minecraft:polished_andesite");
  }

  // Left Main Wheel (X = 5, Z = 4..5, Y = 2..3)
  set(5, 2, 4, "minecraft:black_concrete");
  set(5, 2, 5, "minecraft:black_concrete");
  set(5, 3, 4, "minecraft:black_concrete");
  set(5, 3, 5, "minecraft:black_concrete");
  set(4, 3, 4, "minecraft:polished_andesite_slab[type=bottom]"); // Hub cap

  // Right Main Wheel (X = 9, Z = 4..5, Y = 2..3)
  set(9, 2, 4, "minecraft:black_concrete");
  set(9, 2, 5, "minecraft:black_concrete");
  set(9, 3, 4, "minecraft:black_concrete");
  set(9, 3, 5, "minecraft:black_concrete");
  set(10, 3, 4, "minecraft:polished_andesite_slab[type=bottom]"); // Hub cap

  // V-Struts (Connecting fuselage belly at Y = 4 to wheels/axle at Y = 3)
  set(5, 4, 4, "minecraft:iron_bars");
  set(5, 4, 5, "minecraft:iron_bars");
  set(9, 4, 4, "minecraft:iron_bars");
  set(9, 4, 5, "minecraft:iron_bars");
  set(6, 3, 3, "minecraft:iron_bars");
  set(8, 3, 3, "minecraft:iron_bars");

  // Wheel Chocks (Y = 2)
  set(5, 2, 3, "minecraft:oak_stairs[facing=south,half=bottom]");
  set(5, 2, 6, "minecraft:oak_stairs[facing=north,half=bottom]");
  set(9, 2, 3, "minecraft:oak_stairs[facing=south,half=bottom]");
  set(9, 2, 6, "minecraft:oak_stairs[facing=north,half=bottom]");

  // Tail Skid / Tail Wheel (Y = 2 to 3, Z = 12..13)
  set(7, 3, 12, "minecraft:spruce_fence");
  set(7, 2, 13, "minecraft:dark_oak_stairs[facing=south,half=bottom]");

  // -------------------------------------------------------------
  // 8. FLIGHT LINE ACCESSORIES (Connected solid diorama gear)
  // -------------------------------------------------------------
  if (livery.accessory === "ladder") {
    // Mechanic's wooden boarding ladder at left wing root
    set(4, 2, 6, themeStairs ? `${themeStairs}[facing=north,half=bottom]` : "minecraft:oak_stairs[facing=north,half=bottom]");
    set(4, 3, 6, themeWood);
    set(4, 4, 6, themeSlab ? `${themeSlab}[type=bottom]` : "minecraft:oak_slab[type=bottom]");
    set(4, 2, 5, "minecraft:red_terracotta"); // Metal toolbox
    set(7, 2, 2, "minecraft:polished_andesite_slab[type=bottom]"); // Engine drip tray
  } else if (livery.accessory === "fuel_cart") {
    // Mobile fuel drum cart on right side
    set(10, 2, 6, "minecraft:iron_block");
    set(10, 3, 6, "minecraft:blast_furnace[facing=north]");
    set(10, 2, 7, "minecraft:iron_block");
    set(10, 3, 7, "minecraft:hopper");
    set(9, 4, 6, "minecraft:chain[axis=y]"); // Fueling hose up to wing tank
    set(8, 5, 5, "minecraft:chain[axis=z]");
    set(7, 6, 4, "minecraft:chain[axis=y]");
  } else if (livery.accessory === "tie_downs") {
    // Wingtip ground tie-downs with iron anchor stakes
    set(1, 3, 4, "minecraft:chain[axis=y]");
    set(1, 2, 4, "minecraft:iron_bars");
    set(13, 3, 4, "minecraft:chain[axis=y]");
    set(13, 2, 4, "minecraft:iron_bars");
    set(4, 2, 5, "minecraft:brown_wool"); // Pilot flight bag
  } else if (livery.accessory === "cargo_dolly") {
    // Air-mail cargo crates beside lower wing
    set(10, 2, 5, themeWood);
    set(10, 3, 5, "minecraft:barrel[facing=up]");
    set(10, 2, 6, themeWood);
    set(10, 2, 4, "minecraft:spruce_slab[type=bottom]");
  } else {
    // Ground starter battery trolley at the nose
    set(7, 2, 1, "minecraft:iron_block");
    set(7, 2, 0, "minecraft:lightning_rod[facing=up]");
    set(4, 2, 4, "minecraft:cauldron"); // Oil barrel
    set(4, 3, 4, "minecraft:hopper");
  }

  // -------------------------------------------------------------
  // 9. GROUND CONFORMITY (Rule 6: Follow real terrain)
  // -------------------------------------------------------------
  const groundColumns = [
    // Left wheel & chocks
    [5, 3], [5, 4], [5, 5], [5, 6],
    // Right wheel & chocks
    [9, 3], [9, 4], [9, 5], [9, 6],
    // Tail skid
    [7, 12], [7, 13],
    // Left service accessories
    [4, 4], [4, 5], [4, 6], [1, 4],
    // Right service accessories
    [10, 4], [10, 5], [10, 6], [10, 7], [13, 4],
    // Nose accessories
    [7, 0], [7, 1], [7, 2]
  ];

  for (const [gx, gz] of groundColumns) {
    const terrainH = Math.round(api.heightAt(gx, gz));
    const targetGroundY = seatY + terrainH;

    // Ground falls away (downhill / slope / shore) -> extend legs/skirt down
    if (targetGroundY < seatY) {
      const bottomY = Math.max(0, targetGroundY);
      for (let y = seatY - 1; y >= bottomY; y--) {
        let soleBlock = themePlinth;
        if (gx === 5 || gx === 9) {
          soleBlock = "minecraft:black_concrete"; // Tire extension
        } else if (gx === 1 || gx === 13) {
          soleBlock = "minecraft:iron_bars"; // Tie down stake
        } else if (gz >= 12) {
          soleBlock = themeWood; // Wooden skid base
        }
        set(gx, y, gz, soleBlock);
      }
    }
    // Ground rises above seat plane -> extend foot up to terrain
    else if (targetGroundY > seatY) {
      const topY = Math.min(11, targetGroundY);
      for (let y = seatY; y <= topY; y++) {
        if (!blocks.has(`${gx},${y},${gz}`)) {
          set(gx, y, gz, themePlinth);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 10. EMIT VOXELS TO API
  // -------------------------------------------------------------
  for (const voxel of blocks.values()) {
    api.set(voxel.x, voxel.y, voxel.z, voxel.block);
  }

  return {
    name: "vintage_biplane",
    seatY: 2,
    anchors: {
      front: [7, 5, 0],       // Nose propeller tip facing North
      cockpit: [7, 5, 6],     // Pilot cockpit seat
      fuel_port: [7, 8, 4]    // Gravity fuel tank on upper wing
    }
  };
}
